CREATE TABLE users(id UUID PRIMARY KEY,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(100) NOT NULL,display_name VARCHAR(80) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sessions(id UUID PRIMARY KEY,user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,family UUID NOT NULL,token_hash VARCHAR(64) NOT NULL UNIQUE,expires_at TIMESTAMP WITH TIME ZONE NOT NULL,revoked BOOLEAN NOT NULL DEFAULT FALSE);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE foods(id VARCHAR(100) PRIMARY KEY,name TEXT NOT NULL,brand TEXT NOT NULL,calories NUMERIC,protein NUMERIC,carbs NUMERIC,fat NUMERIC,fiber NUMERIC,source TEXT NOT NULL,source_url TEXT NOT NULL,license TEXT NOT NULL,verification TEXT NOT NULL,source_version TEXT NOT NULL);
CREATE TABLE meals(id UUID PRIMARY KEY,user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,food_id VARCHAR(100) NOT NULL REFERENCES foods(id),grams NUMERIC NOT NULL CHECK(grams>0 AND grams<=5000),meal_type VARCHAR(20) NOT NULL,eaten_at TIMESTAMP WITH TIME ZONE NOT NULL,idempotency_key UUID NOT NULL,snapshot TEXT NOT NULL,UNIQUE(user_id,idempotency_key));
CREATE INDEX meals_user_time ON meals(user_id,eaten_at);
